import type { Metadata } from "next";
import type { BlogPost } from "@/lib/blog";
import { localeUrl, type Locale } from "@/lib/i18n/config";

export const SITE_URL = "https://www.posljiracun.si";
export const SITE_NAME = "Slikaj Račun";
const TITLE_SUFFIX = " — Slikaj Račun";

/** Default social share image (generated by app/opengraph-image.tsx).
 *  Setting `openGraph` on a page replaces the inherited object, so every
 *  page must list the image explicitly or it ships without og:image. */
export const DEFAULT_OG_IMAGE = {
  url: `${SITE_URL}/opengraph-image`,
  width: 1200,
  height: 630,
  alt: "Slikaj Račun — Pošlji račun z enim klikom",
};
export const DEFAULT_TWITTER_IMAGE = `${SITE_URL}/twitter-image`;

interface PageSeoInput {
  title: string;
  description: string;
  /** The Slovenian slug, e.g. "zasebnost". Used to build SL+EN canonical URLs. */
  slug: string;
  /** Which locale this metadata is for. Default: "sl". */
  locale?: Locale;
  /** Optional: explicit URL pair for pages whose SL ↔ EN slugs differ
   *  in unpredictable ways (e.g. blog posts). When provided, the
   *  alternates use these directly instead of the slugMap derivation. */
  altPaths?: { sl: string; en: string };
}

export function pageMetadata({ title, description, slug, locale = "sl", altPaths }: PageSeoInput): Metadata {
  const canonicalPath = altPaths
    ? (locale === "sl" ? altPaths.sl : altPaths.en)
    : localeUrl(locale, slug);
  const url = `${SITE_URL}${canonicalPath}`;

  const slPath = altPaths?.sl ?? localeUrl("sl", slug);
  const enPath = altPaths?.en ?? localeUrl("en", slug);

  return {
    title,
    description,
    alternates: {
      canonical: canonicalPath,
      languages: {
        "sl-SI": slPath,
        "en":    enPath,
        "x-default": slPath,
      },
    },
    openGraph: {
      type: "website",
      locale: locale === "sl" ? "sl_SI" : "en_US",
      alternateLocale: [locale === "sl" ? "en_US" : "sl_SI"],
      siteName: SITE_NAME,
      url,
      title,
      description,
      images: [DEFAULT_OG_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [DEFAULT_TWITTER_IMAGE],
    },
  };
}


export function blogMetadata(post: BlogPost, locale: Locale = "sl"): Metadata {
  const en = locale === "en";
  const base = pageMetadata({
    title: en ? post.titleEn : post.title,
    description: en ? post.descriptionEn : post.description,
    slug: `blog/${post.slug}`, locale,
    altPaths: { sl: `/blog/${post.slug}`, en: `/en/blog/${post.slugEn}` },
  });
  // The layout template appends " — Slikaj Račun" (15 chars). Long article
  // titles would then be truncated in search results, so drop the suffix
  // when the full title would exceed ~60 characters.
  const title = en ? post.titleEn : post.title;
  return {
    ...base,
    title: `${title}${TITLE_SUFFIX}`.length > 60 ? { absolute: title } : title,
    openGraph: {
      ...base.openGraph, type: "article",
      publishedTime: post.publishedAt,
      modifiedTime: post.updatedAt ?? post.publishedAt,
      images: [{ url: post.coverImage, alt: en ? post.coverAltEn : post.coverAlt }],
    },
    twitter: { card: "summary_large_image", title: en ? post.titleEn : post.title, description: en ? post.descriptionEn : post.description, images: [post.coverImage] },
  };
}

export const privateMetadata: Metadata = {
  robots: { index: false, follow: true },
  alternates: { canonical: null, languages: {} },
};
